<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cap-drop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
